seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>')).upper()
comp=str.maketrans('ACGT','TGCA')
def rc(s): return s.translate(comp)[::-1]
r=rc(seq)
stops={'TAA','TAG','TGA'}
n=len(seq)
for strand,s in (('+',seq),('-',r)):
    for f in range(3):
        # find longest stop-free window (in codons) with start/end coords in that strand, convert to forward
        best=(0,None)
        i=f
        cur=f
        pos=f
        runs=[]
        while pos+3<=n:
            if s[pos:pos+3] in stops:
                runs.append((cur,pos))
                cur=pos+3
            pos+=3
        runs.append((cur,pos))
        for a,b in runs:
            if b-a>best[0]:
                best=(b-a,(a,b))
        a,b=best[1]
        if strand=='+':
            fwd=(a+1,b)
        else:
            fwd=(n-b+1,n-a)
        print(strand,f,'longest stop-free nt',best[0],'codons',best[0]//3,' forward coords',fwd)
