            if s[pos:pos+3] in stops:
                if pos-cur>=minlen:
                    if strand=='+': fwd=(cur+1,pos)
                    else: fwd=(n-pos+1,n-cur)
                    res.append((strand,f,cur,pos,fwd,pos-cur))
                cur=pos+3
            pos+=3
        if pos-cur>=minlen:
            if strand=='+': fwd=(cur+1,pos)
            else: fwd=(n-pos+1,n-cur)
            res.append((strand,f,cur,pos,fwd,pos-cur))
    return res
