seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>')).upper()
comp=str.maketrans('ACGT','TGCA')
def rc(s): return s.translate(comp)[::-1]
r=rc(seq)
n=len(seq)
stops={'TAA','TAG','TGA'}
def codons_in(sub_a,sub_b):
    # return dict per strand/frame of (count, stops)
    out={}
    for strand,s in (('+',seq),('-',r)):
        for f in range(3):
            tot=st=0
            i=f
            while i+3<=n:
                # map to forward coords (0-based)
                if strand=='+': fa,fb=i,i+3
                else: fa,fb=n-(i+3),n-i
                if fa>=sub_a and fb<=sub_b:
                    tot+=1
                    if s[i:i+3] in stops: st+=1
                i+=3
            out[strand+str(f)]=(tot,st)
    return out
for name,(a,b) in {'1-791':(0,791),'792-1599':(791,1599),'1600-1744':(1599,1744),'788-1744(B)':(787,1744),'1600-2592(C)':(1599,2592),'2592-3000':(2591,3000)}.items():
    print(name, {k:v for k,v in codons_in(a,b).items()})
"}
